-- =====================================================================
-- 发布表 vs 结算表 修改脚本（以结算表为准）
--   发布表: fa_storage_order_publish
--   结算表: fa_storage_settlement
-- 执行顺序：建议先备份两表 → 依次执行 ①~⑥ → 用末尾 SELECT 复核
-- 数据基准：发布与结算表.xlsx（2026-06 导出口径）
-- =====================================================================

-- ① 保证金修正（14 组 q²公式错误 + 4 组笔误）：deposit_amount 改为 数量×评估价
--    预期影响 18 行
UPDATE fa_storage_order_publish SET deposit_amount = ROUND(evaluate_price*sale_quantity, 2)
WHERE sale_order_no IN ('ma-8aa01cd80030a4b-1','ma-8aa01cd80030aa4-1','ma-8bf1a8d80038a32-1','ma-8bf1a8d80038b9c-1','ma-8bf1aad80038e44-1','ma-8c8d87800039a8d-1','ma-8c8d89400039e44-1','ma-8c8d89400039e44-2','ma-8e8b2a28003c285-1','ma-8eb45530003ce67-1','ma-8eb45530003ce8c-1','ma-8eb45530003ce8d-1','ma-8eb456f8003d28c-1','ma-8f0f1cb0003d75a-1','ma-8f0f1cb0003d75b-1','ma-8f6dcc30003da0c-1','ma-935c3bc80051305-1','ma-94d7ba880053755-1');

-- ② 评估价/保证金：两端评估价不同 2 组，以结算表为准
UPDATE fa_storage_order_publish SET evaluate_price=5640.00, deposit_amount=56400.00 WHERE sale_order_no='ma-9284a8800050bc0-1';
UPDATE fa_storage_order_publish SET evaluate_price=4512.00, deposit_amount=18048.00 WHERE sale_order_no='ma-9284a8800050bc2-1';

-- ③ 作废结算表重复结算行 2 组（保留 FZ202606040227、FZ202606040987）
DELETE FROM fa_storage_settlement WHERE settle_no IN ('FZ202606040228','FZ202606049986');

-- ④ 删除发布表重复发布行 1 组（保留 id=757）
DELETE FROM fa_storage_order_publish WHERE id IN (784);

-- ⑤ 服务费按结算表覆盖（628 组）
--    说明：结算表服务费含(部分)仓储费，口径与发布表不同，以结算表为准
