-- 保证金：执行后应无差异（除③④涉及单号）
SELECT f.sale_order_no, f.sale_quantity, f.evaluate_price, f.deposit_amount AS f_dep,
       j.quantity, j.deposit_amount AS j_dep,
       ROUND(f.deposit_amount - j.deposit_amount, 2) AS diff
FROM fa_storage_order_publish f JOIN fa_storage_settlement j ON j.sale_order_no = f.sale_order_no
